-- 098_project_schedule_closeout.sql
BEGIN;
CREATE TABLE IF NOT EXISTS public.project_schedule_closeout_versions(
 id uuid PRIMARY KEY,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,version_number integer NOT NULL CHECK(version_number>0),status text NOT NULL CHECK(status IN('DRAFT','CONFIRMED')),baseline_completion_date date NOT NULL,actual_completion_date date NOT NULL,completion_variance_days integer NOT NULL,baseline_opening_date date,actual_opening_date date,opening_variance_days integer,delay_drivers jsonb NOT NULL CHECK(jsonb_typeof(delay_drivers)='array'),recovery_actions jsonb NOT NULL CHECK(jsonb_typeof(recovery_actions)='array'),delaying_work_groups jsonb NOT NULL CHECK(jsonb_typeof(delaying_work_groups)='array'),schedule_explanation text NOT NULL CHECK(btrim(schedule_explanation)<>''AND char_length(schedule_explanation)<=3000),created_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version_number)
);CREATE UNIQUE INDEX IF NOT EXISTS project_schedule_closeout_one_confirmed_idx ON public.project_schedule_closeout_versions(project_id)WHERE status='CONFIRMED';
CREATE OR REPLACE FUNCTION private.prevent_schedule_closeout_mutation()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION'PROJECT_SCHEDULE_CLOSEOUT_IMMUTABLE'USING ERRCODE='55000';END;$$;DROP TRIGGER IF EXISTS project_schedule_closeout_immutable ON public.project_schedule_closeout_versions;CREATE TRIGGER project_schedule_closeout_immutable BEFORE UPDATE OR DELETE ON public.project_schedule_closeout_versions FOR EACH ROW EXECUTE FUNCTION private.prevent_schedule_closeout_mutation();
ALTER TABLE public.project_schedule_closeout_versions ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS project_schedule_closeout_select ON public.project_schedule_closeout_versions;CREATE POLICY project_schedule_closeout_select ON public.project_schedule_closeout_versions FOR SELECT TO authenticated USING(public.can_access_project(project_id));REVOKE ALL ON TABLE public.project_schedule_closeout_versions FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_schedule_closeout_versions TO authenticated;
CREATE OR REPLACE FUNCTION public.save_project_schedule_closeout(p_project_id bigint,p_closeout_id uuid,p_delay_drivers jsonb,p_recovery_actions jsonb,p_delaying_work_groups jsonb,p_schedule_explanation text,p_confirm boolean,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();v_role text;req public.write_command_requests%ROWTYPE;baseline_version bigint;baseline_completion date;actual_completion date;baseline_opening date;actual_opening date;version_no integer;state text;result jsonb;
BEGIN SELECT upper(p.role)INTO v_role FROM public.profiles p WHERE p.id=u;IF u IS NULL OR v_role NOT IN('PM','ADMIN')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_SCHEDULE_CLOSEOUT_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_closeout_id IS NULL OR p_client_request_id IS NULL OR jsonb_typeof(COALESCE(p_delay_drivers,'[]'))<>'array'OR jsonb_typeof(COALESCE(p_recovery_actions,'[]'))<>'array'OR jsonb_typeof(COALESCE(p_delaying_work_groups,'[]'))<>'array'OR btrim(COALESCE(p_schedule_explanation,''))=''OR char_length(p_schedule_explanation)>3000 THEN RAISE EXCEPTION'INVALID_PROJECT_SCHEDULE_CLOSEOUT'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'project_closeout.schedule.save',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='project_closeout.schedule.save'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;IF EXISTS(SELECT 1 FROM public.project_schedule_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')THEN RAISE EXCEPTION'PROJECT_SCHEDULE_CLOSEOUT_ALREADY_CONFIRMED'USING ERRCODE='55000';END IF;SELECT schedule_version_id INTO baseline_version FROM public.project_schedule_baselines WHERE project_id=p_project_id ORDER BY baseline_revision_number DESC LIMIT 1;SELECT max(planned_end)INTO baseline_completion FROM public.project_schedule_version_tasks WHERE version_id=baseline_version;SELECT COALESCE(p.actual_construction_completion_date,(SELECT max(actual_end)FROM public.project_gantt_tasks WHERE project_id=p_project_id AND COALESCE(is_archived,false)=false)),p.target_opening_date,p.actual_opening_date INTO actual_completion,baseline_opening,actual_opening FROM public.projects p WHERE p.id=p_project_id;IF baseline_completion IS NULL OR actual_completion IS NULL THEN RAISE EXCEPTION'SCHEDULE_CLOSEOUT_REQUIRES_BASELINE_AND_ACTUAL_COMPLETION'USING ERRCODE='55000';END IF;SELECT COALESCE(max(version_number),0)+1 INTO version_no FROM public.project_schedule_closeout_versions WHERE project_id=p_project_id;state:=CASE WHEN COALESCE(p_confirm,false)THEN'CONFIRMED'ELSE'DRAFT'END;INSERT INTO public.project_schedule_closeout_versions VALUES(p_closeout_id,p_project_id,version_no,state,baseline_completion,actual_completion,actual_completion-baseline_completion,baseline_opening,actual_opening,CASE WHEN baseline_opening IS NULL OR actual_opening IS NULL THEN NULL ELSE actual_opening-baseline_opening END,COALESCE(p_delay_drivers,'[]'),COALESCE(p_recovery_actions,'[]'),COALESCE(p_delaying_work_groups,'[]'),btrim(p_schedule_explanation),u,now());result:=jsonb_build_object('scheduleCloseoutId',p_closeout_id,'versionNumber',version_no,'status',state,'baselineCompletionDate',baseline_completion,'actualCompletionDate',actual_completion,'completionVarianceDays',actual_completion-baseline_completion,'baselineOpeningDate',baseline_opening,'actualOpeningDate',actual_opening,'openingVarianceDays',CASE WHEN baseline_opening IS NULL OR actual_opening IS NULL THEN NULL ELSE actual_opening-baseline_opening END);UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
CREATE OR REPLACE FUNCTION public.get_project_schedule_closeout(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$DECLARE x public.project_schedule_closeout_versions%ROWTYPE;BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_SCHEDULE_CLOSEOUT_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT*INTO x FROM public.project_schedule_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;RETURN jsonb_build_object('projectId',p_project_id,'hasCloseout',x.id IS NOT NULL,'closeout',CASE WHEN x.id IS NULL THEN NULL ELSE jsonb_build_object('scheduleCloseoutId',x.id,'versionNumber',x.version_number,'status',x.status,'baselineCompletionDate',x.baseline_completion_date,'actualCompletionDate',x.actual_completion_date,'completionVarianceDays',x.completion_variance_days,'baselineOpeningDate',x.baseline_opening_date,'actualOpeningDate',x.actual_opening_date,'openingVarianceDays',x.opening_variance_days,'delayDrivers',x.delay_drivers,'recoveryActions',x.recovery_actions,'delayingWorkGroups',x.delaying_work_groups,'scheduleExplanation',x.schedule_explanation,'createdAt',x.created_at)END);END;$$;
REVOKE ALL ON FUNCTION private.prevent_schedule_closeout_mutation()FROM PUBLIC,anon,authenticated,service_role;REVOKE ALL ON FUNCTION public.save_project_schedule_closeout(bigint,uuid,jsonb,jsonb,jsonb,text,boolean,uuid),public.get_project_schedule_closeout(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.save_project_schedule_closeout(bigint,uuid,jsonb,jsonb,jsonb,text,boolean,uuid),public.get_project_schedule_closeout(bigint)TO authenticated;
COMMIT;
